//! @file
//! @brief Implementation of `ITokens` interface
#pragma once

#include "../Interface.h"
#include "../cpp/ZStringView.h"
#include "../cpp/StringView.h"
#include "../../omni/String.h"

//! @brief Latest version of the `ITokens` interface
#define carb_tokens_ITokens_latest CARB_HEXVERSION(2, 1)
//! @brief Default version of the `ITokens` interface
//! External consumers default to v1.1 for backwards compatibility.
//! Internal builds use v2.0 via premake define: carb_tokens_ITokens=carb_tokens_ITokens_latest
#ifndef carb_tokens_ITokens
#    define carb_tokens_ITokens CARB_HEXVERSION(1, 1)
#endif

//! Namespace for `ITokens`.
namespace carb::tokens
{

/**
 * Errors for resolving tokens.
 */
enum class ResolveError
{
    eTruncated, //!< The output was truncated.
    eFailure, //!< Unspecified failure.
};

/**
 * Flags for token resolution algorithm
 */
using ResolveFlags = uint32_t;
const ResolveFlags kResolveFlagNone = 0; //!< Default token resolution process. Unknown tokens are replaced with empty
                                         //!< strings.
const ResolveFlags kResolveFlagLeaveTokenIfNotFound = 1; //!< If cannot resolve token in a string then leave it as is.

} // namespace carb::tokens

#if CARB_VERSION_ATLEAST(carb_tokens_ITokens, 2, 0)
#    include "detail/ITokens2.h"
#else
#    include "detail/ITokens1.h"
#endif
